// Generates supabase/seed.sql from src/data/seed.json (single source of truth for the initial menu).
import { readFileSync } from 'node:fs';
const seed = JSON.parse(readFileSync(new URL('../src/data/seed.json', import.meta.url), 'utf8'));
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const o = seed.outlet;
const out = [
  '-- Generated by `npm run seed:sql`. Do not edit by hand.',
  'begin;',
  `insert into public.outlets (slug, name, tagline, phone, email, announcement, address, about, partner_text, website_url, website_label) values (${[o.slug, o.name, o.tagline, o.phone, o.email, o.announcement, o.address, o.about, o.partnerText, o.websiteUrl, o.websiteLabel].map(q).join(', ')});`,
];
const outletRef = `(select id from public.outlets where slug = ${q(o.slug)})`;
seed.categories.forEach((c, ci) => {
  out.push(`insert into public.categories (outlet_id, name, sort_order) values (${outletRef}, ${q(c.name)}, ${(ci + 1) * 10});`);
  const catRef = `(select id from public.categories where outlet_id = ${outletRef} and name = ${q(c.name)})`;
  let order = 0;
  for (const s of c.sections) {
    for (const [name, price, type, desc = '', size] of s.items) {
      order += 10;
      out.push(
        `insert into public.items (outlet_id, category_id, section, name, description, price, size, food_type, sort_order) values (${outletRef}, ${catRef}, ${q(s.name)}, ${q(name)}, ${q(desc)}, ${price}, ${q(size ?? s.size ?? '')}, ${q(type)}, ${order});`,
      );
    }
  }
});
out.push('commit;', '');
process.stdout.write(out.join('\n'));
